select '18800000-0000-4002-8000-000000000001',save_id,instance_id,package_id,package_hash,version_id,'generated_successor',null,null,id,title||' successor',objective,motivation,constraints,target_refs,difficulty,definition_plan,current_plan,plan_revision,'failed',0,preparation,scheduled_for_day,1,1 from private.world_quests where instance_id=(select instance_id from pg_temp.f3) limit 1;
insert into private.world_quest_events(id,quest_id,save_id,instance_id,day_number,step_index,action,approach,skill,difficulty,preparation_before,preparation_after,hospitality,readiness,chance,draw,outcome,narration,public_news)
select '18800000-0000-4002-8000-000000000010',q.id,q.save_id,q.instance_id,3,0,'attempt','scouting',1,q.difficulty,0,0,0,0,50,99,'failed','Quest A terminal.',false from private.world_quests q where q.instance_id=(select instance_id from pg_temp.f3) and q.origin='authored_milestone' limit 1;
insert into private.world_quest_events(id,quest_id,save_id,instance_id,day_number,step_index,action,approach,skill,difficulty,preparation_before,preparation_after,hospitality,readiness,chance,draw,outcome,narration,public_news)
select '18800000-0000-4002-8000-000000000011',q.id,q.save_id,q.instance_id,1,0,'attempt','scouting',1,q.difficulty,0,0,0,0,50,99,'failed','Quest B terminal.',false from private.world_quests q where q.id='18800000-0000-4002-8000-000000000001';
-- The first dialogue source predates A's terminal receipt; attach an
-- immutable correction/commitment record to it.  A second dialogue source
-- is registered only after the terminal receipt and must miss A's cutoff.
insert into private.world_npc_memories(turn_id,instance_id,kind,text,quote,speaker,importance,entity_refs,save_id,record_root_id,record_version,source_kind,source_id,source_version,source_hash,occurred_day,occurred_sequence,learned_day,learned_sequence,truth_class,disclosure_class,commitment_status,observer_instance_id,related_quest_id)
select '18800000-0000-4000-8000-000000000030',f.instance_id,'promise','Pre-terminal A commitment','Remember this.','npc',3,'{}',f.save_id,extensions.gen_random_uuid(),1,'dialogue_turn','18800000-0000-4000-8000-000000000030',1,private.world_npc_memory_source_hash('dialogue_turn','18800000-0000-4000-8000-000000000030'),1,0,1,0,'attributed','npc_known','unresolved',f.instance_id,q.id from pg_temp.f3 f join private.world_quests q on q.instance_id=f.instance_id and q.origin='authored_milestone';
insert into private.world_npc_dialogue_turns(id,save_id,instance_id,npc_id,version_id,actor_id,message,input_sequence,source_revision,day_number,status,lease_until,result,completed_at) select '18800000-0000-4002-8000-000000000012',save_id,instance_id,npc_id,version_id,'18800000-0000-4000-8000-000000000003','Post-cutoff A source.',1,revision,1,'completed',clock_timestamp()+interval '5 minutes','{"reply":"Too late."}',clock_timestamp() from pg_temp.f3;
select private.world_npc_memory_project_source('dialogue_turn','18800000-0000-4002-8000-000000000012');
insert into private.world_npc_memories(turn_id,instance_id,kind,text,quote,speaker,importance,entity_refs,save_id,record_root_id,record_version,source_kind,source_id,source_version,source_hash,occurred_day,occurred_sequence,learned_day,learned_sequence,truth_class,disclosure_class,observer_instance_id,related_quest_id)
select '18800000-0000-4002-8000-000000000012',f.instance_id,'interaction','Post-cutoff A link','Too late.','npc',3,'{}',f.save_id,extensions.gen_random_uuid(),1,'dialogue_turn','18800000-0000-4002-8000-000000000012',1,private.world_npc_memory_source_hash('dialogue_turn','18800000-0000-4002-8000-000000000012'),1,1,1,1,'attributed','npc_known',f.instance_id,q.id from pg_temp.f3 f join private.world_quests q on q.instance_id=f.instance_id and q.origin='authored_milestone';
update private.world_npc_memory_outbox set status='completed',completed_at=clock_timestamp(),lease_until=null where instance_id=(select instance_id from pg_temp.f3) and source_kind='quest_event';
select private.world_npc_memory_refresh_watermark((select instance_id from pg_temp.f3),'extract','npc-memory-v1');
select is((private.world_npc_memory_request_quest('18800000-0000-4002-8000-000000000010')).status,'pending','terminal quest A requests its own closure');
select is(private.world_npc_memory_schedule_closures((select instance_id from pg_temp.f3)),3,'all same-instance terminal quest closures schedule once');
select ok(exists(select 1 from private.world_npc_memory_summary_sets s join private.world_npc_memory_summary_leaves l on l.set_id=s.id where s.instance_id=(select instance_id from pg_temp.f3) and s.summary_kind='quest_summary' and s.closure_key like '%18800000-0000-4002-8000-000000000010:%' and l.source_kind='quest_event' and l.source_id='18800000-0000-4002-8000-000000000010'),'quest A terminal evidence is included');
select ok(not exists(select 1 from private.world_npc_memory_summary_sets s join private.world_npc_memory_summary_leaves l on l.set_id=s.id where s.instance_id=(select instance_id from pg_temp.f3) and s.summary_kind='quest_summary' and s.closure_key like '%18800000-0000-4002-8000-000000000010:%' and l.source_kind='quest_event' and l.source_id='18800000-0000-4002-8000-000000000011'),'quest A set excludes same-instance quest B evidence');
select ok(exists(select 1 from private.world_npc_memory_summary_sets s join private.world_npc_memory_summary_leaves l on l.set_id=s.id where s.instance_id=(select instance_id from pg_temp.f3) and s.summary_kind='quest_summary' and s.closure_key like '%18800000-0000-4002-8000-000000000010:%' and l.source_id='18800000-0000-4000-8000-000000000030'),'A-linked pre-cutoff commitment source is included');
select ok(not exists(select 1 from private.world_npc_memory_summary_sets s join private.world_npc_memory_summary_leaves l on l.set_id=s.id where s.instance_id=(select instance_id from pg_temp.f3) and s.summary_kind='quest_summary' and s.closure_key like '%18800000-0000-4002-8000-000000000010:%' and l.source_id='18800000-0000-4002-8000-000000000012'),'post-cutoff A-linked source is excluded');
select is((select commitment_status from private.world_npc_memories where text='Pre-terminal A commitment'),'unresolved','closure scheduling does not mutate commitment/correction gameplay state');
select throws_ok($$delete from private.world_npc_memory_closure_requests$$,'PT409',null,'closure requests are append-only');
select * from finish(); rollback;
